"""Serialization of engine data for the development inspector.

This module is the single place that shapes engine internals into the JSON
the inspector frontend consumes. The shapes below are a wire contract — the
frontend mirrors them with Zod schemas (``src/types/skill.ts``); change them
in lock-step.

Skill catalog payload (``GET /data`` → ``skills`` key, engine projects only)::

    {
      "<skill_id>": {
        "id": str,
        "name": str | null,
        "description": str | null,
        "is_default": bool,
        "engine_managed": bool,
        "disabled": bool,
        "sections": [
          {"type": "prose",
           "segments": [{"text": str, "condition": str | null}]},
          {"type": "ordered_block", "block_id": str}
        ],
        "blocks": {
          "<block_id>": {
            "ordered_block_id": str, # compiled "<skill_id>__<block_id>"
            "complete_when": str | null,
            "steps": [ ... ]         # Step dumps, discriminated by "kind";
          }                          # branch lists use the authored "if" key
        },
        "referenced_skills": [str],
        "tool_names": [str],
        "hidden": bool
      },
      ...
    }

``sections`` preserves the authored document order of prose and blocks.
Conditions are shipped as their authored expression strings for display;
evaluation results live in the per-tracker skill state (below), never here —
the catalog is static per loaded model.

Tracker skill state (tracker payloads → ``skill_state`` key)::

    {
      "active_skill":
        {"skill_id": str | null, "ordered_block_id": str, "step_id": str | null}
        | null,                    # null while routing; PENDING frames skipped
      "pending_skills": [
        {"skill_id": str, "name": str | null}
      ],
      "blocks": {
        "<ordered_block_id>": {"status": "active" | "completed" | "inactive"}
      },
      "evaluated_conditions": {"<expr>": bool},
      "memory": {
        "<slot_name>": {
          "value": any,
          "source": "llm" | "tool" | "system" | null,   # null: never written
          "scope": "skill" | "project" | "system",
          "description": str | null
        }
      },
      "tools": {
        "<tool_name>": {"active": bool}   # gate result for the active context
      },
      "llm_calls": [                       # ephemeral, in-process only
        {
          "id": str, "timestamp": float,
          "request_model": str | null, "response_model": str | null,
          "input_tokens": int | null, "output_tokens": int | null,
          "latency_ms": float | null, "time_to_first_token_ms": float | null,
          "tool_names": [str], "gated_tool_names": [str],
          "response_tool_names": [str],
          "prompt_messages": [{...}],
          "response_messages": [{...}] | null,  # null for failed calls
          "is_error": bool, "error_message": str | null
        }
      ]
    }

``evaluated_conditions`` covers every condition expression reachable from the
active skill (prose segments, branch ``if``s, ``complete_when``s, tool gates),
evaluated against that skill's memory view exactly as the engine would —
evaluation failures report ``false``, mirroring the engine's fail-closed
stance. Conditions of non-active skills are not evaluated. ``memory`` is the
active scope's contract view plus reserved ``system.*`` entries.

``tools`` reports the gate result per tool declared for the active
skill/flow context (``resolve_tool_gates``): ``active: false`` means the tool
is currently withheld from the LLM because its ``requires`` gate evaluates
falsy — the Inspector marks such tools disabled. Empty while routing.

``llm_calls`` is the conversation's ephemeral LLM call log
(:mod:`rasa.mantle.llm.call_log`) — a stopgap for the GenAI span channel
(ENG-3003). The records live in process memory only and never touch the
tracker or tracker stores; they exist solely for this payload.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any, Iterable, Optional

import structlog

from rasa.dialogue_understanding.stack.frames.flow_stack_frame import (
    UserFlowStackFrame,
)
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    MantleStackFrameType,
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.llm.call_log import llm_calls_for
from rasa.mantle.memory.manager import PROJECT_NAMESPACE, SYSTEM_NAMESPACE
from rasa.mantle.skills.catalog import (
    SkillCatalog,
    ordered_blocks_in_body,
    prose_segments_from_body,
    target_id_for_frame,
)
from rasa.mantle.skills.conditions import (
    ConditionEvaluationError,
    NextBranch,
    evaluate_expression,
)
from rasa.mantle.skills.skill import (
    OrderedBlock,
    ProseBlock,
    Skill,
    format_ordered_block_target_id,
)
from rasa.mantle.state.provenance import WriteProvenance, iter_slot_writes
from rasa.shared.core.events import OrderedBlockCompleted

if TYPE_CHECKING:
    from rasa.mantle.model_archive.bootstrap import ModelBootstrap
    from rasa.shared.core.trackers import DialogueStateTracker

structlogger = structlog.get_logger()


def serialize_skill_catalog(catalog: SkillCatalog) -> dict[str, Any]:
    """Return the inspector wire payload for *catalog* (see module docstring)."""
    return {
        skill_id: _serialize_skill(skill) for skill_id, skill in catalog.skills.items()
    }


def _serialize_skill(skill: Skill) -> dict[str, Any]:
    """Serialize one skill into the Inspector sections-and-blocks wire shape."""
    blocks = {
        block.block_id: block for block in skill.body if isinstance(block, OrderedBlock)
    }
    return {
        "id": skill.id,
        "name": skill.name,
        "description": skill.description,
        "is_default": skill.is_default,
        "engine_managed": skill.engine_managed,
        "disabled": skill.disabled,
        "hidden": skill.hidden,
        "sections": [_serialize_section(block) for block in skill.body],
        "blocks": {
            block_id: _serialize_ordered_block(skill.id, block)
            for block_id, block in blocks.items()
        },
        "referenced_skills": list(skill.referenced_skills),
        "tool_names": [gate.name for gate in skill.tools],
    }


def _serialize_section(block: ProseBlock | OrderedBlock) -> dict[str, Any]:
    """Serialize one prose or ordered-block section."""
    if isinstance(block, ProseBlock):
        return {
            "type": block.type,
            "segments": [
                {"text": segment.text, "condition": segment.condition}
                for segment in block.segments
            ],
        }
    return {"type": block.type, "block_id": block.block_id}


def _serialize_ordered_block(skill_id: str, block: OrderedBlock) -> dict[str, Any]:
    """Serialize one ordered block for the Inspector wire payload."""
    return {
        "ordered_block_id": format_ordered_block_target_id(skill_id, block.block_id),
        "complete_when": block.complete_when,
        "steps": [step.model_dump(mode="json", by_alias=True) for step in block.steps],
    }


# ---------------------------------------------------------------------------
# Per-tracker skill state
# ---------------------------------------------------------------------------

_STATUS_ACTIVE = "active"
_STATUS_COMPLETED = "completed"
_STATUS_INACTIVE = "inactive"

_SOURCE_TOOL = "tool"
_SOURCE_LLM = "llm"
_SOURCE_SYSTEM = "system"

_PROJECT_SLOT_PREFIX = f"{PROJECT_NAMESPACE}."
_SYSTEM_SLOT_PREFIX = f"{SYSTEM_NAMESPACE}."


def empty_skill_state() -> dict[str, Any]:
    """Return a skill state with nothing active and no data.

    Emitted when :func:`build_skill_state` fails, so the frontend clears its
    display instead of keeping the previous tracker's state (payloads without
    the key leave the last state in place).
    """
    return {
        "active_skill": None,
        "pending_skills": [],
        "blocks": {},
        "evaluated_conditions": {},
        "tools": {},
        "llm_calls": [],
        "memory": {},
    }


def build_skill_state(
    tracker: "DialogueStateTracker",
    model_bootstrap: "ModelBootstrap",
) -> dict[str, Any]:
    """Return the per-tracker skill state payload (see module docstring).

    Read-only over the tracker: builds a turn handle for stack and memory
    access but never applies events.
    """
    from rasa.mantle.state.tracker_handle import make_tracker_handle

    handle = make_tracker_handle(tracker, model_bootstrap)
    catalog = model_bootstrap.skill_catalog

    frame = _live_inspector_frame(handle)
    if frame is not None:
        skill_id, flow_id = handle.memory.resolve_scope(frame)
    else:
        skill_id, flow_id = "", ""
    active_skill_def = catalog.skill_by_id(skill_id) if skill_id else None
    # Conditions and tool gates must mirror the active skill's contract view (the
    # LLM sees only what it may read). The memory payload, by contrast, is a
    # developer surface and shows every written field across all skills.
    readable_entries = handle.memory.read_all(skill_id, flow_id)
    memory_values = {name: entry.value for name, entry in readable_entries.items()}
    all_entries = handle.memory.read_all_for_inspector()

    active_skill: Optional[dict[str, Any]] = None
    if frame is not None:
        active_skill = {
            "skill_id": skill_id or getattr(frame, "skill_id", None),
            "ordered_block_id": _compiled_flow_id(frame) or "",
            "step_id": getattr(frame, "step_id", None),
        }

    return {
        "active_skill": active_skill,
        "pending_skills": _pending_skill_payload(handle, catalog),
        "blocks": _block_statuses(tracker, catalog, handle),
        "evaluated_conditions": _evaluated_conditions(active_skill_def, memory_values),
        "memory": _memory_payload(tracker, all_entries),
        "tools": _tool_gate_statuses(catalog, skill_id, flow_id, memory_values),
        "llm_calls": llm_calls_for(tracker.sender_id),
    }


def _live_inspector_frame(handle: Any) -> Optional[Any]:
    """Topmost skill/block/flow frame that is not a pending precondition target.

    Pending consumers must not populate ``active_skill``: they have not been
    activated yet, so their instructions and tool gates are not live.
    """
    for frame in reversed(handle.stack.frames):
        if _is_pending_mantle_frame(frame):
            continue
        if isinstance(
            frame, (SkillStackFrame, OrderedBlockStackFrame, UserFlowStackFrame)
        ):
            return frame
    return None


def _is_pending_mantle_frame(frame: object) -> bool:
    return (
        isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame))
        and frame.frame_type == MantleStackFrameType.PENDING
    )


def _pending_skill_payload(handle: Any, catalog: SkillCatalog) -> list[dict[str, Any]]:
    """Parked precondition consumers, bottom-to-top, for the Inspector badge."""
    pending: list[dict[str, Any]] = []
    for frame in handle.stack.frames:
        if not (
            isinstance(frame, SkillStackFrame)
            and frame.frame_type == MantleStackFrameType.PENDING
        ):
            continue
        skill = catalog.skill_by_id(frame.skill_id)
        pending.append(
            {
                "skill_id": frame.skill_id,
                "name": skill.name if skill is not None else None,
            }
        )
    return pending


def _block_statuses(
    tracker: "DialogueStateTracker",
    catalog: SkillCatalog,
    handle: Any,
) -> dict[str, dict[str, Any]]:
    """Status per ordered-block flow id, across all skills in the catalog.

    A block is ``active`` while a stack frame runs it (topmost or not),
    ``completed`` once an ``OrderedBlockCompleted`` event for it exists in the
    current session, and ``inactive`` otherwise. Active wins over completed so
    a re-entered block shows as running.
    """
    stacked_flow_ids: set[str] = set()
    for frame in (
        *handle.skill_and_block_frames(),
        *handle.user_flow_frames(),
    ):
        if _is_pending_mantle_frame(frame):
            continue
        flow_id = _compiled_flow_id(frame)
        if flow_id is not None:
            stacked_flow_ids.add(flow_id)
    completed_flow_ids = {
        format_ordered_block_target_id(event.skill_id, event.block_id)
        for event in tracker.events_after_latest_restart()
        if isinstance(event, OrderedBlockCompleted)
    }

    statuses: dict[str, dict[str, Any]] = {}
    for skill in catalog.skills.values():
        for block in ordered_blocks_in_body(skill):
            flow_id = format_ordered_block_target_id(skill.id, block.block_id)
            if flow_id in stacked_flow_ids:
                status = _STATUS_ACTIVE
            elif flow_id in completed_flow_ids:
                status = _STATUS_COMPLETED
            else:
                status = _STATUS_INACTIVE
            statuses[flow_id] = {"status": status}
    return statuses


def _compiled_flow_id(frame: object) -> Optional[str]:
    """Return the compiled flow id for an inspector stack frame, if any."""
    if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
        return target_id_for_frame(frame)
    if isinstance(frame, UserFlowStackFrame):
        return frame.flow_id
    return None


def _tool_gate_statuses(
    catalog: SkillCatalog,
    skill_id: Optional[str],
    flow_id: Optional[str],
    memory_values: dict[str, Any],
) -> dict[str, dict[str, Any]]:
    """Gate result per tool declared for the active skill/flow context.

    Uses the same gate resolution and fail-closed evaluation as the LLM
    schema builder (``tool_gate_statuses``), so ``active: false`` here means
    exactly "not offered to the LLM right now". Empty while routing (no
    active skill).
    """
    from rasa.mantle.llm.tool_schemas import tool_gate_statuses

    if not skill_id:
        return {}
    statuses = tool_gate_statuses(catalog, skill_id, flow_id, memory_values)
    return {name: {"active": active} for name, active in statuses.items()}


def _evaluated_conditions(
    skill: Optional[Skill],
    memory_values: dict[str, Any],
) -> dict[str, bool]:
    """Evaluate every condition reachable from *skill* against *memory_values*.

    Keyed by the authored expression string — the same strings the catalog
    payload carries — so the frontend joins the two without any positional
    bookkeeping. Failures evaluate to ``False`` (the engine's fail-closed
    behaviour for prose scoping, ``requires`` gates, and tool gates).
    """
    if skill is None:
        return {}

    results: dict[str, bool] = {}
    for expression in _skill_condition_expressions(skill):
        try:
            results[expression] = bool(evaluate_expression(expression, memory_values))
        except ConditionEvaluationError:
            results[expression] = False
    return results


def _yield_unique_condition(
    expression: Optional[str],
    seen: set[str],
) -> Iterable[str]:
    """Yield *expression* once if it is non-empty and not already in *seen*."""
    if expression and expression not in seen:
        seen.add(expression)
        yield expression


def _instruction_segment_conditions(
    skill: Skill,
    seen: set[str],
) -> Iterable[str]:
    for segment in prose_segments_from_body(skill):
        yield from _yield_unique_condition(segment.condition, seen)


def _next_branch_conditions(
    next_value: Any,
    seen: set[str],
) -> Iterable[str]:
    if not isinstance(next_value, list):
        return
    for branch in next_value:
        if isinstance(branch, NextBranch):
            yield from _yield_unique_condition(branch.if_, seen)


def _ordered_block_condition_expressions(
    block: OrderedBlock,
    seen: set[str],
) -> Iterable[str]:
    yield from _yield_unique_condition(block.complete_when, seen)
    for gate in block.tools:
        yield from _yield_unique_condition(gate.requires, seen)
    for step in block.steps:
        yield from _yield_unique_condition(getattr(step, "complete_when", None), seen)
        yield from _next_branch_conditions(getattr(step, "next", None), seen)


def _skill_condition_expressions(skill: Skill) -> Iterable[str]:
    """Yield each distinct condition expression authored on *skill*."""
    seen: set[str] = set()
    yield from _instruction_segment_conditions(skill, seen)
    complete_when = skill.complete_when
    if complete_when is not None:
        yield from _yield_unique_condition(complete_when.condition, seen)
    for gate in skill.tools:
        yield from _yield_unique_condition(gate.requires, seen)
    for block in ordered_blocks_in_body(skill):
        yield from _ordered_block_condition_expressions(block, seen)


def _memory_payload(
    tracker: "DialogueStateTracker",
    memory_entries: dict[str, Any],
) -> dict[str, dict[str, Any]]:
    """Memory map for the inspector: contract view plus ``system.*`` entries."""
    provenance_by_slot = _latest_provenance_by_slot(tracker)

    payload: dict[str, dict[str, Any]] = {}
    for slot_name, entry in memory_entries.items():
        payload[slot_name] = {
            "value": entry.value,
            "source": _write_source(provenance_by_slot.get(slot_name)),
            "scope": _slot_scope(slot_name),
            "description": entry.field.description,
        }

    for slot_name, value in tracker.current_slot_values().items():
        if not slot_name.startswith(_SYSTEM_SLOT_PREFIX) or slot_name in payload:
            continue
        payload[slot_name] = {
            "value": value,
            "source": _write_source(provenance_by_slot.get(slot_name)),
            "scope": _SOURCE_SYSTEM,
            "description": None,
        }

    return payload


def _latest_provenance_by_slot(
    tracker: "DialogueStateTracker",
) -> dict[str, WriteProvenance]:
    """Provenance of each slot's *newest* write, one pass over the session.

    An unstamped write clears the slot's entry: the displayed value then came
    from that write, so keeping an older stamped write's badge would attribute
    the value to the wrong producer.
    """
    latest: dict[str, WriteProvenance] = {}
    for event, provenance in iter_slot_writes(tracker.events_after_latest_restart()):
        if provenance is not None:
            latest[event.key] = provenance
        else:
            latest.pop(event.key, None)
    return latest


def _write_source(provenance: Optional[WriteProvenance]) -> Optional[str]:
    """Map a write's provenance to its display source.

    A producing tool means a builder tool wrote the value; a step without a
    tool means the LLM recorded it (``set_fields`` at that step); provenance
    with neither is an engine-internal write. Unstamped slots (never written
    this session, or written before provenance existed) yield ``None`` so the
    UI omits the badge rather than guessing.
    """
    if provenance is None:
        return None
    if provenance.tool:
        return _SOURCE_TOOL
    if provenance.step:
        return _SOURCE_LLM
    return _SOURCE_SYSTEM


def _slot_scope(slot_name: str) -> str:
    """Classify a fully-qualified slot name into its namespace scope."""
    if slot_name.startswith(_SYSTEM_SLOT_PREFIX):
        return "system"
    if slot_name.startswith(_PROJECT_SLOT_PREFIX):
        return "project"
    return "skill"
